var paths=new [] {"Assets/Test/PlayerReactions/Animations/Test_GetUp.fbx","Assets/Arts/Characters/Player/Models/Test_CheonPlayer.fbx","Assets/Temp/PlayerReactionRawProbe/Test_GetUpNeutral.fbx"};
return paths.Select(path=> {var i=(UnityEditor.ModelImporter)UnityEditor.AssetImporter.GetAtPath(path);var so=new UnityEditor.SerializedObject(i);var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(path);return new {path,root=prefab==null?"missing":prefab.name,skeleton=i.humanDescription.skeleton.Take(7).Select(b=>new{b.name,p=b.position.ToString(),r=b.rotation.eulerAngles.ToString()}).ToArray(),warnings=so.FindProperty("m_AnimationRetargetingWarnings")?.stringValue,errors=so.FindProperty("m_AnimationImportErrors")?.stringValue, hierarchy=prefab==null?new string[0]:prefab.GetComponentsInChildren<Transform>(true).Take(6).Select(t=>t.name).ToArray()};}).ToArray();
